async function buildContext() {
  const env = process.env;
  const warnings = [];
  let llm = new DemoLLMProvider();
  const aiProvider = (env.AI_PROVIDER ?? "demo").toLowerCase();
  try {
    if (aiProvider === "anthropic") {
      if (!env.ANTHROPIC_API_KEY) warnings.push("AI_PROVIDER=anthropic but ANTHROPIC_API_KEY is missing \u2014 using demo provider.");
      else {
        const { AnthropicLLMProvider: AnthropicLLMProvider2 } = await Promise.resolve().then(() => (init_anthropic(), anthropic_exports));
        llm = new AnthropicLLMProvider2(env.ANTHROPIC_API_KEY, env.ANTHROPIC_MODEL || "claude-opus-5");
      }
    } else if (aiProvider === "openai") {
      if (!env.OPENAI_API_KEY) warnings.push("AI_PROVIDER=openai but OPENAI_API_KEY is missing \u2014 using demo provider.");
      else {
        const { OpenAILLMProvider: OpenAILLMProvider2 } = await Promise.resolve().then(() => (init_openai(), openai_exports));
        llm = new OpenAILLMProvider2(env.OPENAI_API_KEY, env.OPENAI_MODEL || "gpt-4o-mini");
      }
    } else if (aiProvider === "groq") {
      if (!env.GROQ_API_KEY) warnings.push("AI_PROVIDER=groq but GROQ_API_KEY is missing \u2014 using demo provider.");
      else {
        const { OpenAILLMProvider: OpenAILLMProvider2 } = await Promise.resolve().then(() => (init_openai(), openai_exports));
        llm = new OpenAILLMProvider2(env.GROQ_API_KEY, env.GROQ_MODEL || "openai/gpt-oss-120b", "https://api.groq.com/openai/v1");
      }
    } else if (aiProvider !== "demo") {
      warnings.push(`Unknown AI_PROVIDER "${aiProvider}" \u2014 using demo provider.`);
    }
  } catch (e) {
    warnings.push(`LLM provider initialisation failed (${e.message}) \u2014 using demo provider.`);
    llm = new DemoLLMProvider();
  }
  let embeddings = new LocalEmbeddingProvider();
  const embProvider = (env.EMBEDDING_PROVIDER ?? "local").toLowerCase();
  try {
    if (embProvider === "voyage") {
      if (!env.VOYAGE_API_KEY) warnings.push("EMBEDDING_PROVIDER=voyage but VOYAGE_API_KEY is missing \u2014 using local embeddings.");
      else {
        const { VoyageEmbeddingProvider: VoyageEmbeddingProvider2 } = await Promise.resolve().then(() => (init_openai(), openai_exports));
        embeddings = new VoyageEmbeddingProvider2(env.VOYAGE_API_KEY, env.VOYAGE_EMBEDDING_MODEL || "voyage-3-lite");
      }
    }
  } catch (e) {
    warnings.push(`Embedding provider initialisation failed (${e.message}) \u2014 using local embeddings.`);
    embeddings = new LocalEmbeddingProvider();
  }
  let repo;
  const supaKey = env.SUPABASE_SECRET_KEY || env.SUPABASE_SERVICE_ROLE_KEY;
  if (env.SUPABASE_URL && supaKey) {
    try {
      const { SupabaseStandardsRepository: SupabaseStandardsRepository2 } = await Promise.resolve().then(() => (init_supabaseRepository(), supabaseRepository_exports));
      const supa = new SupabaseStandardsRepository2(env.SUPABASE_URL, supaKey);
      const info = await supa.datasetInfo();
      if (info.standardCount === 0) {
        warnings.push("Supabase is configured but the standards table is empty \u2014 using the in-memory demo dataset. Run `npm run ingest`.");
        repo = new MemoryStandardsRepository(loadDemoDataset(), embeddings);
      } else repo = supa;
    } catch (e) {
      warnings.push(`Supabase connection failed (${e.message}) \u2014 using the in-memory demo dataset.`);
      repo = new MemoryStandardsRepository(loadDemoDataset(), embeddings);
    }
  } else {
    repo = new MemoryStandardsRepository(loadDemoDataset(), embeddings);
  }
  if (repo.name.startsWith("supabase") && embeddings.name === "local") {
    warnings.push("Supabase repository with local embeddings: vector search will fall back to full-text search unless the index was built with the same provider.");
  }
  return {
    ai: { llm, embeddings },
    repo,
    mode: llm.isLive ? "live" : "demo",
    warnings,
    maxUploadMb: Number(env.MAX_UPLOAD_MB) || 10
  };
}

